INSERT INTO companies (id, slug, email, phone, logo_url, location, postal_code, country_code, timezone,
INSERT INTO company_translations (company_id, language_id, name, description, street, neighborhood, city, region)
VALUES
    ('b1c47b09-e8d1-4e86-be48-f593744e1088', '11111122-2222-4111-8111-111111111112', 'Λεπίδα & Λόγος', 'Το Λεπίδα & Λόγος άνοιξε το 2014 σε ένα διατηρητέο ισόγειο της Υμηττού, λίγα βήματα από την πλατεία Βαρνάβα, και έγινε γρήγορα σημείο αναφοράς για το Παγκράτι. Τέσσερις μπαρμπέρηδες δουλεύουν σε βάρδιες από νωρίς το πρωί ως αργά το βράδυ, με έμφαση στο ψαλίδι, τα καθαρά fade και το παραδοσιακό ξύρισμα με ζεστή πετσέτα. Κάθε ραντεβού ξεκινά με μια σύντομη κουβέντα για το στυλ και τελειώνει με styling και συμβουλές για το σπίτι. Ο χώρος συνδυάζει δρύινους πάγκους, vintage καρέκλες κουρείου και μια μικρή βιβλιοθήκη για όσους περιμένουν. Τα Σάββατα γεμίζουν από νωρίς, γι'' αυτό κλείσε ραντεβού online μερικές μέρες πριν.', 'Υμηττού 72', 'Παγκράτι', 'Αθήνα', 'Αττική'),
    ('b1c47b09-e8d1-4e86-be48-f593744e1088', '11111122-2222-4111-8111-111111111111', 'Lepida & Logos Barber House', 'Lepida & Logos opened in 2014 in a listed ground-floor space on Ymittou Street, a few steps from Varnava Square, and quickly became a Pangrati landmark. Four barbers work in shifts from early morning until late evening, with a focus on scissor work, clean fades and the traditional hot-towel shave. Every appointment starts with a short chat about style and ends with styling and advice for home. The space combines oak counters, vintage barber chairs and a small library for those waiting. Saturdays fill up early, so book online a few days ahead.', 'Ymittou 72', 'Pangrati', 'Athens', 'Attica'),
    ('c9d5998f-becd-4568-83b4-5f83025a667d', '11111122-2222-4111-8111-111111111112', 'Ατελιέ Κουρέματος Αριστείδης', 'Ατελιέ κουρέματος στην καρδιά του Κολωνακίου, με τρεις θέσεις και ραντεβού μόνο κατόπιν κράτησης. Ο Αριστείδης δουλεύει κυρίως με ψαλίδι και προσαρμόζει κάθε κούρεμα στο σχήμα του προσώπου. Η εμπειρία κλείνει με λούσιμο, styling και ένα ποτήρι ρακί για όσους το θέλουν.', 'Σκουφά 28', 'Κολωνάκι', 'Αθήνα', 'Αττική'),
    ('c9d5998f-becd-4568-83b4-5f83025a667d', '11111122-2222-4111-8111-111111111111', 'Aristeidis Grooming Atelier', 'A grooming atelier in the heart of Kolonaki, with three chairs and appointments by booking only. Aristeidis works mainly with scissors and shapes every cut to the face. The visit ends with a wash, styling and a glass of raki for those who want one.', 'Skoufa 28', 'Kolonaki', 'Athens', 'Attica'),
    ('a22fa02e-37bd-46ac-82ba-c74e6859b5f1', '11111122-2222-4111-8111-111111111112', 'Γραμμή Μηδέν', 'Νεανικό κουρείο στο Κουκάκι με ειδίκευση στα skin fade, τα taper και τα καθαρά line-up. Η ομάδα παρακολουθεί τις τάσεις και ανεβάζει κάθε εβδομάδα νέες δουλειές στο portfolio της.', 'Βεΐκου 45', 'Κουκάκι', 'Αθήνα', 'Αττική'),
    ('a22fa02e-37bd-46ac-82ba-c74e6859b5f1', '11111122-2222-4111-8111-111111111111', 'Grammi Miden Barbers', 'A young barbershop in Koukaki that specializes in skin fades, tapers and sharp line-ups. The team follows the trends and adds new work to its portfolio every week.', 'Veikou 45', 'Koukaki', 'Athens', 'Attica'),
    ('2665614f-521e-4126-b924-bd20fdb18a03', '11111122-2222-4111-8111-111111111112', 'Το Γένι', 'Μικρό beard bar στα Εξάρχεια, αφιερωμένο στα γένια κάθε μήκους. Σχήμα με ξυράφι, ζεστές πετσέτες, λάδια και βάλσαμα με φυσικά υλικά. Το κούρεμα υπάρχει, αλλά τα γένια είναι ο λόγος που έρχεται ο κόσμος.', 'Θεμιστοκλέους 62', 'Εξάρχεια', 'Αθήνα', 'Αττική'),
    ('2665614f-521e-4126-b924-bd20fdb18a03', '11111122-2222-4111-8111-111111111111', 'To Geni Beard Bar', 'A small beard bar in Exarchia, devoted to beards of every length. Razor shaping, hot towels, oils and balms made with natural ingredients. Haircuts are on the menu, but beards are why people come.', 'Themistokleous 62', 'Exarchia', 'Athens', 'Attica'),
    ('a1cc6fc7-8590-4cf4-b229-a3dc7cd00a71', '11111122-2222-4111-8111-111111111112', 'Κουρείο της Δέσποινας', 'Η Δέσποινα κόβει μαλλιά στη Φωκίωνος Νέγρη πάνω από είκοσι χρόνια και ξέρει τους περισσότερους πελάτες με το μικρό τους όνομα. Κλασικά ανδρικά κουρέματα, προσεγμένο ξύρισμα και τιμές γειτονιάς.', 'Φωκίωνος Νέγρη 34', 'Κυψέλη', 'Αθήνα', 'Αττική'),
    ('a1cc6fc7-8590-4cf4-b229-a3dc7cd00a71', '11111122-2222-4111-8111-111111111111', 'Despina''s Barbershop', 'Despina has been cutting hair on Fokionos Negri for over twenty years and knows most of her customers by first name. Classic men''s cuts, careful shaves and neighborhood prices.', 'Fokionos Negri 34', 'Kypseli', 'Athens', 'Attica'),
    ('bcc7b8d3-77ce-4adf-988d-2d5e44ff3e1d', '11111122-2222-4111-8111-111111111112', 'Κουρείο Τα Αδέρφια', 'Οικογενειακό κουρείο στο Χαλάνδρι από το 1978, που σήμερα το κρατά η δεύτερη γενιά. Τα αδέρφια Κωνσταντίνου κουρεύουν παππούδες, γονείς και εγγόνια στις ίδιες καρέκλες που αγόρασε ο πατέρας τους.', 'Αγίας Παρασκευής 48', 'Χαλάνδρι', 'Χαλάνδρι', 'Αττική'),
    ('bcc7b8d3-77ce-4adf-988d-2d5e44ff3e1d', '11111122-2222-4111-8111-111111111111', 'Ta Aderfia Barbershop', 'A family barbershop in Chalandri since 1978, now run by the second generation. The Konstantinou brothers cut grandfathers, fathers and grandsons in the same chairs their father bought.', 'Agias Paraskevis 48', 'Chalandri', 'Chalandri', 'Attica'),
    ('1b525029-e54a-492e-b4df-b57f3e8d6247', '11111122-2222-4111-8111-111111111112', 'Πόλος Barbers', 'Σύγχρονο κουρείο δίπλα στην κεντρική πλατεία του Αμαρουσίου, ιδανικό για ένα γρήγορο fade πριν ή μετά τη δουλειά. Ανοιχτό από τις 8 το πρωί, με online κράτηση και ελάχιστη αναμονή.', 'Ερμού 18', 'Μαρούσι', 'Μαρούσι', 'Αττική'),
    ('1b525029-e54a-492e-b4df-b57f3e8d6247', '11111122-2222-4111-8111-111111111111', 'Polos Barbers', 'A modern barbershop next to the main square of Marousi, ideal for a quick fade before or after work. Open from 8 in the morning, with online booking and very little waiting.', 'Ermou 18', 'Marousi', 'Marousi', 'Attica'),
    ('e309846c-32de-4862-b06b-c0364976c0e7', '11111122-2222-4111-8111-111111111112', 'Αλμύρα Grooming Lounge', 'Premium grooming lounge στο κέντρο της Γλυφάδας, με ατμόσφαιρα beach club και θέα στη Μεταξά. Κουρέματα, περιποίηση γενιών, μάσκες προσώπου και θεραπείες τριχωτού σε ένα χαλαρό, φωτεινό περιβάλλον.', 'Μεταξά 22', 'Γλυφάδα', 'Γλυφάδα', 'Αττική'),
    ('e309846c-32de-4862-b06b-c0364976c0e7', '11111122-2222-4111-8111-111111111111', 'Almyra Grooming Lounge', 'A premium grooming lounge in central Glyfada, with a beach-club feel and a view over Metaxa Street. Cuts, beard care, face masks and scalp treatments in a relaxed, bright setting.', 'Metaxa 22', 'Glyfada', 'Glyfada', 'Attica'),
    ('b40d79f1-afda-4853-8d57-54d00c07b735', '11111122-2222-4111-8111-111111111112', 'Κουρείο Πλάτανος', 'Κομψό κουρείο κάτω από τα πλατάνια της Κηφισιάς, με δερμάτινες πολυθρόνες και ήσυχη ατμόσφαιρα. Εξειδικεύεται στο κλασικό κούρεμα με ψαλίδι και στο grey blending για φυσικό αποτέλεσμα.', 'Κυριαζή 14', 'Κηφισιά', 'Κηφισιά', 'Αττική'),
    ('b40d79f1-afda-4853-8d57-54d00c07b735', '11111122-2222-4111-8111-111111111111', 'Platanos Barbershop', 'An elegant barbershop under the plane trees of Kifisia, with leather armchairs and a quiet atmosphere. It specializes in classic scissor cuts and grey blending for a natural result.', 'Kyriazi 14', 'Kifisia', 'Kifisia', 'Attica'),
    ('bf8a02c9-a2d8-47c3-82ec-90b4e996dc96', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ο Μπάμπης', 'Λαϊκό κουρείο στην Τσαλδάρη με σταθερές, χαμηλές τιμές και γρήγορο σέρβις. Ο Μπάμπης και ο ανιψιός του δέχονται και χωρίς ραντεβού, αλλά με κράτηση δεν περιμένεις καθόλου.', 'Παναγή Τσαλδάρη 75', NULL, 'Περιστέρι', 'Αττική'),
    ('bf8a02c9-a2d8-47c3-82ec-90b4e996dc96', '11111122-2222-4111-8111-111111111111', 'Babis Barbershop', 'A no-frills barbershop on Tsaldari Street with steady, low prices and fast service. Babis and his nephew take walk-ins, but with a booking you do not wait at all.', 'Panagi Tsaldari 75', NULL, 'Peristeri', 'Attica'),
    ('81885a0e-c352-4ba2-a59d-1ba1bad44b9c', '11111122-2222-4111-8111-111111111112', 'Κουρείο Λιμάνι', 'Κλασικό κουρείο λίγα στενά από το λιμάνι του Πειραιά, με καθρέφτες της δεκαετίας του ''60 και μυρωδιά από κολόνια λεμόνι. Ναυτικοί, φοιτητές και επαγγελματίες της περιοχής έρχονται εδώ για καθαρό κούρεμα και ξύρισμα με ξυράφι.', 'Ηρώων Πολυτεχνείου 54', NULL, 'Πειραιάς', 'Αττική'),
    ('81885a0e-c352-4ba2-a59d-1ba1bad44b9c', '11111122-2222-4111-8111-111111111111', 'Limani Barbershop', 'A classic barbershop a few streets from the port of Piraeus, with 1960s mirrors and the scent of lemon cologne. Sailors, students and local professionals come here for a clean cut and a straight-razor shave.', 'Iroon Polytechneiou 54', NULL, 'Piraeus', 'Attica'),
    ('39083534-0598-4801-97f4-db3206debf0a', '11111122-2222-4111-8111-111111111112', 'Κουρείο Η Μαργαρίτα', 'Φιλικό οικογενειακό κουρείο στη Νέα Σμύρνη, λίγο πριν από την πλατεία. Η Μαργαρίτα έχει γωνιά με παιχνίδια και παιδική καρέκλα σε σχήμα αυτοκινήτου, οπότε το πρώτο κούρεμα γίνεται παιχνίδι.', 'Ομήρου 30', 'Νέα Σμύρνη', 'Νέα Σμύρνη', 'Αττική'),
    ('39083534-0598-4801-97f4-db3206debf0a', '11111122-2222-4111-8111-111111111111', 'Margarita''s Family Barbers', 'A friendly family barbershop in Nea Smyrni, just before the main square. Margarita keeps a toy corner and a car-shaped kids'' chair, so a first haircut turns into a game.', 'Omirou 30', 'Nea Smyrni', 'Nea Smyrni', 'Attica'),
    ('8803cb55-1eea-46f6-9548-285131326dae', '11111122-2222-4111-8111-111111111112', 'Γρήγορο Ψαλίδι', 'Express κουρείο στην Καλλιθέα για όσους θέλουν καλό κούρεμα σε είκοσι λεπτά. Τέσσερις θέσεις, συνεχές ωράριο και τιμές που δεν αλλάζουν κάθε χρόνο.', 'Δαβάκη 40', 'Καλλιθέα', 'Καλλιθέα', 'Αττική'),
    ('8803cb55-1eea-46f6-9548-285131326dae', '11111122-2222-4111-8111-111111111111', 'Grigoro Psalidi', 'An express barbershop in Kallithea for anyone who wants a good cut in twenty minutes. Four chairs, all-day hours and prices that do not change every year.', 'Davaki 40', 'Kallithea', 'Kallithea', 'Attica'),
    ('e5bd6809-3883-40cf-b9c5-edb102369441', '11111122-2222-4111-8111-111111111112', 'Αντίθεση Barber Studio', 'Industrial χώρος με μπετό, νέον και βινύλια στους Αμπελοκήπους. Οι μπαρμπέρηδες της Αντίθεσης είναι γνωστοί για τα textured crop, τα σχέδια με ξυράφι και τα τολμηρά χρώματα.', 'Πανόρμου 18', 'Αμπελόκηποι', 'Αθήνα', 'Αττική'),
    ('e5bd6809-3883-40cf-b9c5-edb102369441', '11111122-2222-4111-8111-111111111111', 'Antithesi Barber Studio', 'An industrial space with concrete, neon and vinyl records in Ampelokipoi. Antithesi''s barbers are known for textured crops, razor designs and bold colors.', 'Panormou 18', 'Ampelokipoi', 'Athens', 'Attica'),
    ('18cf4c29-9238-4755-a50a-d283f5e37acc', '11111122-2222-4111-8111-111111111112', 'Το Στέκι του Κουρέα', 'Το αγαπημένο κουρείο των φοιτητών του Ζωγράφου, δύο στάσεις από την Πανεπιστημιούπολη. Φοιτητική τιμή με το πάσο, μουσική από τους πελάτες και ραντεβού μέχρι αργά το βράδυ.', 'Παπάγου 92', 'Ζωγράφου', 'Ζωγράφου', 'Αττική'),
    ('18cf4c29-9238-4755-a50a-d283f5e37acc', '11111122-2222-4111-8111-111111111111', 'To Steki Barbers', 'The favorite barbershop of Zografou''s students, two bus stops from the university campus. Student prices with a student card, music picked by the customers and appointments until late.', 'Papagou 92', 'Zografou', 'Zografou', 'Attica'),
    ('c2dceeb4-f1db-4ab7-9b5f-a8efa48bd76f', '11111122-2222-4111-8111-111111111112', 'Κατερίνα Hair & Barber', 'Μοντέρνο οικογενειακό κουρείο στην Ηλιούπολη, όπου η Κατερίνα και η ομάδα της κουρεύουν άνδρες και παιδιά κάθε ηλικίας. Ξεχωρίζει για την υπομονή με τους μικρούς πελάτες και τα προσεγμένα κουρέματα για μπαμπά και γιο.', 'Σοφοκλή Βενιζέλου 120', 'Ηλιούπολη', 'Ηλιούπολη', 'Αττική'),
    ('c2dceeb4-f1db-4ab7-9b5f-a8efa48bd76f', '11111122-2222-4111-8111-111111111111', 'Katerina Hair & Barber', 'A modern family barbershop in Ilioupoli, where Katerina and her team cut men and children of every age. It stands out for its patience with young customers and its careful father-and-son cuts.', 'Sofokli Venizelou 120', 'Ilioupoli', 'Ilioupoli', 'Attica'),
    ('8eb4d781-a1a3-47cd-a072-8dd26331da95', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ο Νίκος', 'Κουρείο της γειτονιάς πάνω στην Ιερά Οδό, κοντά στον σταθμό του μετρό. Καθαρά, γρήγορα και οικονομικά, με τον Νίκο να μετράει τριάντα χρόνια στη δουλειά.', 'Ιερά Οδός 384', NULL, 'Αιγάλεω', 'Αττική'),
    ('8eb4d781-a1a3-47cd-a072-8dd26331da95', '11111122-2222-4111-8111-111111111111', 'Nikos Barbershop', 'A neighborhood barbershop on Iera Odos, close to the metro station. Clean, fast and affordable, with Nikos counting thirty years in the trade.', 'Iera Odos 384', NULL, 'Aigaleo', 'Attica'),
    ('6d6c3db3-b362-4c52-bbaf-0c9494b5be4d', '11111122-2222-4111-8111-111111111112', 'Ευγένεια Gentlemen''s Grooming', 'Ιδιωτικό grooming studio στο Νέο Ψυχικό, με δύο μόνο θέσεις και απόλυτη διακριτικότητα. Κάθε ραντεβού κρατά τουλάχιστον μία ώρα και περιλαμβάνει συμβουλή στυλ, κούρεμα, ξύρισμα και περιποίηση προσώπου.', 'Αγίου Δημητρίου 3', 'Νέο Ψυχικό', 'Ψυχικό', 'Αττική'),
    ('6d6c3db3-b362-4c52-bbaf-0c9494b5be4d', '11111122-2222-4111-8111-111111111111', 'Evgeneia Gentlemen''s Grooming', 'A private grooming studio in Neo Psychiko with only two chairs and complete discretion. Every appointment lasts at least an hour and includes style advice, a cut, a shave and facial care.', 'Agiou Dimitriou 3', 'Neo Psychiko', 'Psychiko', 'Attica'),
    ('fe1248a2-a5b2-4552-8e89-78e68bcf66a3', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ο Θανάσης', 'Παραδοσιακό κουρείο στον Βύρωνα, με τον Θανάση πίσω από την καρέκλα από το 1991. Κλασικά κουρέματα, ξύρισμα με ξυράφι και κουβέντα για ποδόσφαιρο, όλα σε τιμή γειτονιάς.', 'Καραολή Δημητρίου 40', 'Βύρωνας', 'Βύρωνας', 'Αττική'),
    ('fe1248a2-a5b2-4552-8e89-78e68bcf66a3', '11111122-2222-4111-8111-111111111111', 'Thanasis Barbershop', 'A traditional barbershop in Vyronas, with Thanasis behind the chair since 1991. Classic cuts, razor shaves and football talk, all at neighborhood prices.', 'Karaoli Dimitriou 40', 'Vyronas', 'Vyronas', 'Attica'),
    ('f0dd9691-ba00-4ddf-85d9-fd10d188e05f', '11111122-2222-4111-8111-111111111112', 'Ξυράφι Φαλήρου', 'Κουρείο στο Παλαιό Φάληρο με ειδίκευση στα γένια και στο παραδοσιακό ξύρισμα. Οι μπαρμπέρηδες χρησιμοποιούν λεπίδες μιας χρήσης, ζεστό αφρό και after shave με ευκάλυπτο από τοπικό εργαστήριο.', 'Αγίου Αλεξάνδρου 30', 'Παλαιό Φάληρο', 'Παλαιό Φάληρο', 'Αττική'),
    ('f0dd9691-ba00-4ddf-85d9-fd10d188e05f', '11111122-2222-4111-8111-111111111111', 'Xyrafi Faliro', 'A Palaio Faliro barbershop that specializes in beards and traditional shaves. The barbers use single-use blades, warm lather and a eucalyptus aftershave from a local workshop.', 'Agiou Alexandrou 30', 'Palaio Faliro', 'Palaio Faliro', 'Attica'),
    ('f94dace7-14ea-4523-ae3a-081797ec2f87', '11111122-2222-4111-8111-111111111112', 'Κουρείο Μικροί & Μεγάλοι', 'Το κουρείο του Αλίμου που αγαπούν τα παιδιά, με κινούμενα σχέδια στην οθόνη, καραμέλες χωρίς ζάχαρη και δίπλωμα πρώτου κουρέματος. Οι γονείς κουρεύονται στη διπλανή καρέκλα, την ίδια ώρα.', 'Καλαμακίου 45', 'Άλιμος', 'Άλιμος', 'Αττική'),
    ('f94dace7-14ea-4523-ae3a-081797ec2f87', '11111122-2222-4111-8111-111111111111', 'Mikroi & Megaloi Barbershop', 'The Alimos barbershop that kids love, with cartoons on the screen, sugar-free sweets and a first-haircut certificate. Parents get their cut in the next chair, at the same time.', 'Kalamakiou 45', 'Alimos', 'Alimos', 'Attica'),
    ('10bbd812-3bbb-4528-8634-12c8c786cfe6', '11111122-2222-4111-8111-111111111112', 'Ρότα Barbers', 'Σύγχρονο κουρείο στην Αγία Παρασκευή, με τέσσερις μπαρμπέρηδες και μπαρ καφέ στην είσοδο. Fade, crop και κλασικά κουρέματα, με αυστηρή τήρηση της ώρας κάθε ραντεβού.', 'Αγίου Ιωάννου 52', 'Αγία Παρασκευή', 'Αγία Παρασκευή', 'Αττική'),
    ('10bbd812-3bbb-4528-8634-12c8c786cfe6', '11111122-2222-4111-8111-111111111111', 'Rota Barbers', 'A modern barbershop in Agia Paraskevi with four barbers and a coffee bar at the entrance. Fades, crops and classic cuts, with strict respect for every appointment time.', 'Agiou Ioannou 52', 'Agia Paraskevi', 'Agia Paraskevi', 'Attica'),
    ('cfc1b886-4941-4c17-af2c-8e99c8bc7fed', '11111122-2222-4111-8111-111111111112', 'Κουρείο της Βάσως', 'Η Βάσω άνοιξε το κουρείο της στον Χολαργό το 2009 και από τότε κουρεύει τρεις γενιές από τις ίδιες οικογένειες. Ζεστό, καθαρό μαγαζί με φιλικές τιμές και ειδική τιμή για 65+.', 'Περικλέους 30', 'Χολαργός', 'Χολαργός', 'Αττική'),
    ('cfc1b886-4941-4c17-af2c-8e99c8bc7fed', '11111122-2222-4111-8111-111111111111', 'Vaso''s Barbershop', 'Vaso opened her barbershop in Cholargos in 2009 and has cut three generations of the same families since then. A warm, clean shop with friendly prices and a special rate for customers over 65.', 'Perikleous 30', 'Cholargos', 'Cholargos', 'Attica'),
    ('5ae1b7a0-1675-4a23-9d48-8bf53523059c', '11111122-2222-4111-8111-111111111112', 'Αλκής ο Μπαρμπέρης', 'Ο Αλκής είναι γνωστός στα Πετράλωνα για τα μακριά, περιποιημένα γένια και τα κουρέματα με vintage ύφος. Το μαγαζί έχει δερμάτινες καρέκλες, μουσική rockabilly και δικά του λάδια για γένια.', 'Τρώων 52', 'Πετράλωνα', 'Αθήνα', 'Αττική'),
    ('5ae1b7a0-1675-4a23-9d48-8bf53523059c', '11111122-2222-4111-8111-111111111111', 'Alkis the Barber', 'Alkis is known in Petralona for long, well-kept beards and vintage-style cuts. The shop has leather chairs, rockabilly on the speakers and its own beard oils.', 'Troon 52', 'Petralona', 'Athens', 'Attica'),
    ('4a0b081c-4148-4576-b491-5fcd1b9f8f12', '11111122-2222-4111-8111-111111111112', 'Νέον Κουρείο', 'Κουρείο με φωτισμό νέον και βραδινό ωράριο στην Ψυρρή, ιδανικό για ένα fade πριν από την έξοδο. Δέχεται ραντεβού έως τις 22:00 από Πέμπτη έως Σάββατο.', 'Αισχύλου 12', 'Ψυρρή', 'Αθήνα', 'Αττική'),
    ('4a0b081c-4148-4576-b491-5fcd1b9f8f12', '11111122-2222-4111-8111-111111111111', 'Neon Barbers', 'A neon-lit barbershop with late hours in Psyrri, ideal for a fade before a night out. Appointments run until 22:00 from Thursday to Saturday.', 'Aischylou 12', 'Psyrri', 'Athens', 'Attica'),
    ('5722a109-c20e-4981-bf12-387b4a686eda', '11111122-2222-4111-8111-111111111112', 'Κουρείο Φωταέριο', 'Δίπλα στην Τεχνόπολη, το Φωταέριο συνδυάζει βιομηχανικό ντιζάιν με σύγχρονα κουρέματα και hair design. Οι μπαρμπέρηδες φτιάχνουν γραμμές και σχέδια με ξυράφι κατά παραγγελία.', 'Περσεφόνης 30', 'Γκάζι', 'Αθήνα', 'Αττική'),
    ('5722a109-c20e-4981-bf12-387b4a686eda', '11111122-2222-4111-8111-111111111111', 'Fotaerio Barbers', 'Next to Technopolis, Fotaerio blends industrial design with modern cuts and hair design. The barbers create custom lines and razor patterns on request.', 'Persefonis 30', 'Gazi', 'Athens', 'Attica'),
    ('5bc90e61-f494-4714-ab05-01753c2f4fde', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ο Τάσος', 'Απλό, καθαρό κουρείο στη Μεταμόρφωση με σταθερή πελατεία και πάρκινγκ μπροστά στο μαγαζί. Ο Τάσος κάνει γρήγορα κλασικά κουρέματα και πακέτο κούρεμα με γένια σε πολύ καλή τιμή.', '28ης Οκτωβρίου 18', NULL, 'Μεταμόρφωση', 'Αττική'),
    ('5bc90e61-f494-4714-ab05-01753c2f4fde', '11111122-2222-4111-8111-111111111111', 'Tasos Barbershop', 'A simple, clean barbershop in Metamorfosi with loyal regulars and parking right outside. Tasos does fast classic cuts and a cut-and-beard package at a very good price.', '28is Oktovriou 18', NULL, 'Metamorfosi', 'Attica'),
    ('1175c810-a003-4e29-9d71-60b1665b28cb', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ιωνία 1968', 'Από το 1968 στη Λεωφόρο Ηρακλείου, το κουρείο κρατά ζωντανή την παράδοση των μαστόρων της Νέας Ιωνίας. Ξύρισμα με πινέλο και ζεστή πετσέτα, κολόνια στο τέλος και καμία βιασύνη.', 'Λεωφόρος Ηρακλείου 280', 'Νέα Ιωνία', 'Νέα Ιωνία', 'Αττική'),
    ('1175c810-a003-4e29-9d71-60b1665b28cb', '11111122-2222-4111-8111-111111111111', 'Ionia 1968 Barbershop', 'On Irakleiou Avenue since 1968, this barbershop keeps alive the tradition of the old master barbers of Nea Ionia. Brush-lathered shaves with a hot towel, cologne at the end and no rush.', 'Irakleiou Avenue 280', 'Nea Ionia', 'Nea Ionia', 'Attica'),
    ('0ca576d9-d433-49f2-91a1-bcc30e45569c', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ο Λευτέρης', 'Μικρό κουρείο στον Νέο Κόσμο, πέντε λεπτά από τη στάση του τραμ. Καλά κουρέματα σε χαμηλές τιμές, και ο Λευτέρης θυμάται πάντα πώς το θέλεις.', 'Φραντζή 22', 'Νέος Κόσμος', 'Αθήνα', 'Αττική'),
    ('0ca576d9-d433-49f2-91a1-bcc30e45569c', '11111122-2222-4111-8111-111111111111', 'Lefteris Barbershop', 'A small barbershop in Neos Kosmos, five minutes from the tram stop. Good cuts at low prices, and Lefteris always remembers how you like it.', 'Frantzi 22', 'Neos Kosmos', 'Athens', 'Attica'),
    ('5916ff51-b280-4ab2-b6a7-f7998343f23b', '11111122-2222-4111-8111-111111111112', 'Κουρείο Η Ιωάννα', 'Φωτεινό οικογενειακό κουρείο στα Βριλήσσια, με χώρο αναμονής για γονείς και παιδιά. Η Ιωάννα έχει εκπαιδευτεί σε κουρέματα για παιδιά με αισθητηριακή ευαισθησία και δουλεύει με αθόρυβα εργαλεία.', 'Λεωφόρος Πεντέλης 70', 'Βριλήσσια', 'Βριλήσσια', 'Αττική'),
    ('5916ff51-b280-4ab2-b6a7-f7998343f23b', '11111122-2222-4111-8111-111111111111', 'Ioanna''s Family Barbers', 'A bright family barbershop in Vrilissia, with a waiting area for parents and children. Ioanna has trained in haircuts for children with sensory sensitivities and works with quiet tools.', 'Pentelis Avenue 70', 'Vrilissia', 'Vrilissia', 'Attica'),
    ('aa3172a9-6f26-40cf-8a19-62da98273b7f', '11111122-2222-4111-8111-111111111112', 'Mikrolimano Barber Club', 'Barber club με θέα στο Μικρολίμανο, όπου το κούρεμα συνοδεύεται από espresso ή ουίσκι. Premium υπηρεσίες για μαλλιά και γένια, με έμφαση στο ξύρισμα με ζεστή πετσέτα.', 'Ακτή Κουμουνδούρου 34', 'Καστέλλα', 'Πειραιάς', 'Αττική'),
    ('aa3172a9-6f26-40cf-8a19-62da98273b7f', '11111122-2222-4111-8111-111111111111', 'Mikrolimano Barber Club', 'A barber club overlooking Mikrolimano, where a cut comes with an espresso or a whisky. Premium hair and beard services, with a focus on the hot-towel shave.', 'Akti Koumoundourou 34', 'Kastella', 'Piraeus', 'Attica'),
    ('85851389-b522-41d6-930a-5e5c8c85e5f1', '11111122-2222-4111-8111-111111111112', 'Κουρείο Αύρα', 'Ανάλαφρο, παραθαλάσσιο κουρείο στη Βούλα με μεγάλα παράθυρα και φυτά παντού. Μοντέρνα κουρέματα, fade και περιποίηση γενιών, με προϊόντα χωρίς θειικά άλατα.', 'Βασιλέως Παύλου 72', 'Βούλα', 'Βούλα', 'Αττική'),
    ('85851389-b522-41d6-930a-5e5c8c85e5f1', '11111122-2222-4111-8111-111111111111', 'Avra Barbers', 'A breezy seaside barbershop in Voula with large windows and plants everywhere. Modern cuts, fades and beard care, with sulfate-free products.', 'Vasileos Pavlou 72', 'Voula', 'Voula', 'Attica'),
    ('349e4c6f-d3b7-4542-899c-2284e5bf1bde', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ο Παντελής', 'Κουρείο με παράδοση στα Ιλίσια, κοντά στο Μέγαρο Μουσικής. Ο Παντελής κουρεύει δικηγόρους, γιατρούς και φοιτητές με το ίδιο προσεγμένο κλασικό κούρεμα.', 'Μιχαλακοπούλου 98', 'Ιλίσια', 'Αθήνα', 'Αττική'),
    ('349e4c6f-d3b7-4542-899c-2284e5bf1bde', '11111122-2222-4111-8111-111111111111', 'Pantelis Barbershop', 'A traditional barbershop in Ilisia, near the Athens Concert Hall. Pantelis gives lawyers, doctors and students the same careful classic cut.', 'Michalakopoulou 98', 'Ilisia', 'Athens', 'Attica'),
    ('65a4b4a7-65e4-4c6d-9ca1-7b533d566a90', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ο Σάκης', 'Κουρείο της γειτονιάς στη Λεωφόρο Βεΐκου, με γρήγορο σέρβις και πάντα καλή διάθεση. Οι τιμές είναι από τις χαμηλότερες στο Γαλάτσι και η καθαριότητα άψογη.', 'Λεωφόρος Βεΐκου 75', 'Γαλάτσι', 'Γαλάτσι', 'Αττική'),
    ('65a4b4a7-65e4-4c6d-9ca1-7b533d566a90', '11111122-2222-4111-8111-111111111111', 'Sakis Barbershop', 'A neighborhood barbershop on Veikou Avenue, with fast service and a good mood every day. Prices are among the lowest in Galatsi and the shop is spotless.', 'Veikou Avenue 75', 'Galatsi', 'Galatsi', 'Attica'),
    ('06c39c31-90a2-43a5-9124-4655e6ccd319', '11111122-2222-4111-8111-111111111112', 'Αλάτι & Πιπέρι Barbers', 'Σύγχρονο κουρείο στα Λαδάδικα, με ειδίκευση στο grey blending και στα κουρέματα για γκρίζα μαλλιά. Η ομάδα πιστεύει ότι τα γκρίζα δεν κρύβονται, αλλά αναδεικνύονται.', 'Κατουνίου 12', 'Λαδάδικα', 'Θεσσαλονίκη', 'Κεντρική Μακεδονία'),
    ('06c39c31-90a2-43a5-9124-4655e6ccd319', '11111122-2222-4111-8111-111111111111', 'Alati & Piperi Barbers', 'A modern barbershop in Ladadika that specializes in grey blending and cuts for grey hair. The team believes grey is not something to hide but something to show.', 'Katouniou 12', 'Ladadika', 'Thessaloniki', 'Central Macedonia'),
    ('88383a27-ca77-4501-8fb8-6add4522ce57', '11111122-2222-4111-8111-111111111112', 'Βασιλικόν Grooming', 'Premium κουρείο στον πρώτο όροφο ενός νεοκλασικού στην Τσιμισκή. Κουρέματα με ψαλίδι, ξύρισμα με ζεστή πετσέτα και περιποίηση προσώπου με προϊόντα από ελληνικά βότανα.', 'Τσιμισκή 78', 'Κέντρο', 'Θεσσαλονίκη', 'Κεντρική Μακεδονία'),
    ('88383a27-ca77-4501-8fb8-6add4522ce57', '11111122-2222-4111-8111-111111111111', 'Vasilikon Grooming', 'A premium barbershop on the first floor of a neoclassical building on Tsimiski Street. Scissor cuts, hot-towel shaves and facial care with products made from Greek herbs.', 'Tsimiski 78', 'City Center', 'Thessaloniki', 'Central Macedonia'),
    ('27acf4a2-a099-43b0-bca3-621e567fc058', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ο Στέλιος', 'Ο κυρ Στέλιος άνοιξε το κουρείο στην Κομνηνών το 1978 και σήμερα δουλεύει δίπλα στον γιο του. Οικογενειακή ατμόσφαιρα, παιδικά κουρέματα και σταθερή ποιότητα εδώ και τέσσερις δεκαετίες.', 'Κομνηνών 40', 'Καλαμαριά', 'Καλαμαριά', 'Κεντρική Μακεδονία'),
    ('27acf4a2-a099-43b0-bca3-621e567fc058', '11111122-2222-4111-8111-111111111111', 'Stelios Barbershop', 'Mr Stelios opened the shop on Komninon Street in 1978 and today works next to his son. A family atmosphere, kids'' cuts and steady quality for four decades.', 'Komninon 40', 'Kalamaria', 'Kalamaria', 'Central Macedonia'),
    ('068bfa31-21f9-46cb-8592-88fe35ff7037', '11111122-2222-4111-8111-111111111112', 'Κουρείο της Σοφίας', 'Η Σοφία κρατά ένα από τα πιο αγαπημένα κουρεία της Τούμπας, με κλασικά κουρέματα και ξύρισμα όπως παλιά. Οι πελάτες επιστρέφουν για τα χέρια της και για τον ελληνικό καφέ στην αναμονή.', 'Παπαναστασίου 110', 'Τούμπα', 'Θεσσαλονίκη', 'Κεντρική Μακεδονία'),
    ('068bfa31-21f9-46cb-8592-88fe35ff7037', '11111122-2222-4111-8111-111111111111', 'Sofia''s Barbershop', 'Sofia runs one of the best-loved barbershops in Toumba, with classic cuts and old-school shaves. Customers come back for her skill and for the Greek coffee while they wait.', 'Papanastasiou 110', 'Toumba', 'Thessaloniki', 'Central Macedonia'),
    ('00fab928-ebb1-4e2f-b000-d1c8c62ac48a', '11111122-2222-4111-8111-111111111112', 'Το Κάστρο', 'Μικρό πέτρινο κουρείο στην Άνω Πόλη, κάτω από τα κάστρα. Ειδικεύεται στα γένια, στο ξύρισμα με ξυράφι και στα κλασικά κουρέματα με ψαλίδι.', 'Ολυμπιάδος 80', 'Άνω Πόλη', 'Θεσσαλονίκη', 'Κεντρική Μακεδονία'),
    ('00fab928-ebb1-4e2f-b000-d1c8c62ac48a', '11111122-2222-4111-8111-111111111111', 'To Kastro Barbershop', 'A small stone-built barbershop in Ano Poli, below the city walls. It specializes in beards, straight-razor shaves and classic scissor cuts.', 'Olympiados 80', 'Ano Poli', 'Thessaloniki', 'Central Macedonia'),
    ('9f8fd526-14b4-4c88-979f-b73169fe76dd', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ρυθμός', 'Γρήγορο, οικονομικό κουρείο κοντά στο Αριστοτέλειο Πανεπιστήμιο. Φοιτητικές τιμές όλη την εβδομάδα και ραντεβού ανά δεκαπέντε λεπτά για όσους βιάζονται.', 'Εθνικής Αμύνης 12', 'Κέντρο', 'Θεσσαλονίκη', 'Κεντρική Μακεδονία'),
    ('9f8fd526-14b4-4c88-979f-b73169fe76dd', '11111122-2222-4111-8111-111111111111', 'Rythmos Barbers', 'A fast, budget barbershop near Aristotle University. Student prices all week and appointments every fifteen minutes for anyone in a hurry.', 'Ethnikis Amynis 12', 'City Center', 'Thessaloniki', 'Central Macedonia'),
    ('ee822d69-cfec-4246-b619-1ddbc8634b16', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ο Γιάννης', 'Οικογενειακό κουρείο στη Σταυρούπολη, με τον Γιάννη στην καρέκλα και τη σύζυγό του στο ταμείο. Κουρέματα για όλη την οικογένεια, γωνιά για παιδιά και άνετο πάρκινγκ στο πλάι.', 'Λαγκαδά 150', 'Σταυρούπολη', 'Σταυρούπολη', 'Κεντρική Μακεδονία'),
    ('ee822d69-cfec-4246-b619-1ddbc8634b16', '11111122-2222-4111-8111-111111111111', 'Giannis Barbershop', 'A family barbershop in Stavroupoli, with Giannis at the chair and his wife at the front desk. Cuts for the whole family, a kids'' corner and easy parking on the side street.', 'Lagkada 150', 'Stavroupoli', 'Stavroupoli', 'Central Macedonia'),
    ('2cd900b7-2c9d-4492-bcb8-303d9058dbf8', '11111122-2222-4111-8111-111111111112', 'Θέα Barber Lounge', 'Grooming lounge στο Πανόραμα με θέα στον Θερμαϊκό από τις καρέκλες. Premium κουρέματα, βαφή και θεραπείες τριχωτού, σε έναν ήσυχο χώρο με ραντεβού μόνο κατόπιν κράτησης.', 'Κομνηνών 20', 'Πανόραμα', 'Πανόραμα', 'Κεντρική Μακεδονία'),
    ('2cd900b7-2c9d-4492-bcb8-303d9058dbf8', '11111122-2222-4111-8111-111111111111', 'Thea Barber Lounge', 'A grooming lounge in Panorama with a view of the Thermaic Gulf from the chairs. Premium cuts, color and scalp treatments in a quiet space, by appointment only.', 'Komninon 20', 'Panorama', 'Panorama', 'Central Macedonia'),
    ('dd0cf77a-dd01-4822-a165-e05cd4ecc178', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ο Αχαιός', 'Κλασικό κουρείο στο κέντρο της Πάτρας, λίγα μέτρα από την πλατεία Γεωργίου. Οι μάστορες του Αχαιού κόβουν με ψαλίδι και χτένα, όπως έμαθαν από τους παλιούς.', 'Ρήγα Φεραίου 120', 'Κέντρο', 'Πάτρα', 'Δυτική Ελλάδα'),
    ('dd0cf77a-dd01-4822-a165-e05cd4ecc178', '11111122-2222-4111-8111-111111111111', 'Achaios Barbershop', 'A classic barbershop in central Patras, a few meters from Georgiou Square. The barbers at Achaios cut with scissors and comb, the way the old masters taught them.', 'Riga Feraiou 120', 'City Center', 'Patras', 'Western Greece'),
    ('e5a9c51a-568d-4b02-9d32-d1991908457f', '11111122-2222-4111-8111-111111111112', 'Ελένη Barber Studio', 'Μοντέρνο barber studio στη Μαιζώνος με γυναικεία ματιά στο ανδρικό κούρεμα. Η Ελένη και η ομάδα της κάνουν fade, crop και χρώμα, με πολλή προσοχή στη λεπτομέρεια.', 'Μαιζώνος 180', 'Κέντρο', 'Πάτρα', 'Δυτική Ελλάδα'),
    ('e5a9c51a-568d-4b02-9d32-d1991908457f', '11111122-2222-4111-8111-111111111111', 'Eleni Barber Studio', 'A modern barber studio on Maizonos Street that brings a woman''s eye to men''s cuts. Eleni and her team do fades, crops and color with close attention to detail.', 'Maizonos 180', 'City Center', 'Patras', 'Western Greece'),
    ('7faad484-98ec-4961-a424-39caea384fd1', '11111122-2222-4111-8111-111111111112', 'Κουρείο Λαβύρινθος', 'Σύγχρονο κουρείο στον πεζόδρομο της Δαιδάλου, στο κέντρο του Ηρακλείου. Δημοφιλές στους νέους για τα fade και τα σχέδια, αλλά και στους επισκέπτες που θέλουν ένα γρήγορο κούρεμα.', 'Δαιδάλου 20', 'Κέντρο', 'Ηράκλειο', 'Κρήτη'),
    ('7faad484-98ec-4961-a424-39caea384fd1', '11111122-2222-4111-8111-111111111111', 'Labyrinthos Barbers', 'A modern barbershop on the Daidalou pedestrian street in central Heraklion. Popular with young locals for fades and designs, and with visitors who want a quick cut.', 'Daidalou 20', 'City Center', 'Heraklion', 'Crete'),
    ('8678993c-1235-4fb8-84c1-76d7334f07b6', '11111122-2222-4111-8111-111111111112', 'Κουρείο Ο Μανώλης', 'Ο Μανώλης κουρεύει στον Πόρο εδώ και δεκαπέντε χρόνια, με κρητική φιλοξενία και ρακί για τους τακτικούς. Κλασικά κουρέματα και περιποίηση για γένια και μουστάκι.', 'Λεωφόρος Ικάρου 45', 'Πόρος', 'Ηράκλειο', 'Κρήτη'),
    ('8678993c-1235-4fb8-84c1-76d7334f07b6', '11111122-2222-4111-8111-111111111111', 'Manolis Barbershop', 'Manolis has been cutting hair in Poros for fifteen years, with Cretan hospitality and raki for the regulars. Classic cuts plus beard and mustache care.', 'Ikarou Avenue 45', 'Poros', 'Heraklion', 'Crete'),
    ('61077097-4ea3-4d85-b4db-da6c34447f78', '11111122-2222-4111-8111-111111111112', 'Κουρείο Πηνειός', 'Οικογενειακό κουρείο στο κέντρο της Λάρισας, με χώρο για καροτσάκια και παιδική καρέκλα. Γρήγορα, προσεγμένα κουρέματα για μπαμπάδες και παιδιά, από Δευτέρα έως Σάββατο.', 'Παπαναστασίου 80', NULL, 'Λάρισα', 'Θεσσαλία'),
    ('61077097-4ea3-4d85-b4db-da6c34447f78', '11111122-2222-4111-8111-111111111111', 'Pineios Barbershop', 'A family barbershop in central Larissa, with room for strollers and a kids'' chair. Fast, careful cuts for dads and kids, Monday to Saturday.', 'Papanastasiou 80', NULL, 'Larissa', 'Thessaly'),
    ('8a3170b9-d8f1-4614-b72d-7ffe76371819', '11111122-2222-4111-8111-111111111112', 'Κουρείο της Λίμνης', 'Κλασικό κουρείο στη Μιχαήλ Αγγέλου, λίγα βήματα από τη λίμνη Παμβώτιδα. Σοβαρή δουλειά με ψαλίδι, ξύρισμα με ξυράφι και ήρεμη ατμόσφαιρα.', 'Μιχαήλ Αγγέλου 22', 'Κέντρο', 'Ιωάννινα', 'Ήπειρος'),
    ('8a3170b9-d8f1-4614-b72d-7ffe76371819', '11111122-2222-4111-8111-111111111111', 'Limni Barbershop', 'A classic barbershop on Michail Angelou Street, a short walk from Lake Pamvotida. Serious scissor work, straight-razor shaves and a calm atmosphere.', 'Michail Angelou 22', 'City Center', 'Ioannina', 'Epirus'),
    ('3d6d9c49-b953-456d-b9a1-592bd813e0c9', '11111122-2222-4111-8111-111111111112', 'Κουρείο Αργώ', 'Κουρείο με ναυτικό ύφος στον Βόλο, αφιερωμένο στα γένια και στο παραδοσιακό ξύρισμα. Οι μπαρμπέρηδες φτιάχνουν δικά τους βάλσαμα με κερί μέλισσας από το Πήλιο.', 'Ερμού 110', NULL, 'Βόλος', 'Θεσσαλία'),
    ('3d6d9c49-b953-456d-b9a1-592bd813e0c9', '11111122-2222-4111-8111-111111111111', 'Argo Barbers', 'A nautical-themed barbershop in Volos, devoted to beards and traditional shaves. The barbers make their own balms with beeswax from Mount Pelion.', 'Ermou 110', NULL, 'Volos', 'Thessaly'),
    ('952dceeb-e96d-4507-83e6-cd58e666e3d2', '11111122-2222-4111-8111-111111111112', 'Κουρείο Η Αργυρώ', 'Η Αργυρώ κουρεύει στην Παλιά Πόλη των Χανίων, σε ένα μαγαζί με πέτρινους τοίχους λίγο πάνω από το λιμάνι. Κλασικά ανδρικά και παιδικά κουρέματα, με ζεστή κρητική φιλοξενία.', 'Χάληδων 40', 'Παλιά Πόλη', 'Χανιά', 'Κρήτη'),
    ('952dceeb-e96d-4507-83e6-cd58e666e3d2', '11111122-2222-4111-8111-111111111111', 'Argyro''s Barbershop', 'Argyro cuts hair in the Old Town of Chania, in a stone-walled shop just above the harbor. Classic men''s and kids'' cuts, with warm Cretan hospitality.', 'Chalidon 40', 'Old Town', 'Chania', 'Crete');
