INSERT INTO service_translations (service_id, language_id, name, description)
VALUES
    ('1039690e-103e-48c4-b255-77e541f43295', '11111122-2222-4111-8111-111111111112', 'Κλασικό κούρεμα', 'Κούρεμα με μηχανή και ψαλίδι, με λούσιμο και απλό styling στο τέλος.'),
    ('1039690e-103e-48c4-b255-77e541f43295', '11111122-2222-4111-8111-111111111111', 'Classic haircut', 'A clipper and scissor cut, finished with a wash and simple styling.'),
    ('5ac794ec-3837-4951-802a-13db02a864b1', '11111122-2222-4111-8111-111111111112', 'Κούρεμα & γένια', 'Κλασικό κούρεμα μαζί με περιποίηση και σχήμα γενιών στην ίδια επίσκεψη.'),
    ('5ac794ec-3837-4951-802a-13db02a864b1', '11111122-2222-4111-8111-111111111111', 'Haircut & beard', 'A classic cut plus beard trim and shaping in the same visit.'),
    ('0dbc7f38-d710-41ca-bde2-952e1bc404ff', '11111122-2222-4111-8111-111111111112', 'Skin fade', 'Fade που ξεκινά από το δέρμα στα πλάγια και σβήνει ομαλά προς τα επάνω.'),
    ('0dbc7f38-d710-41ca-bde2-952e1bc404ff', '11111122-2222-4111-8111-111111111111', 'Skin fade', 'A fade that starts at the skin on the sides and blends smoothly upward.'),
    ('0a4fe7ec-d076-4e50-bf2f-17dfc898978e', '11111122-2222-4111-8111-111111111112', 'Περιποίηση γενιών', 'Κόντεμα και ίσιωμα γενιών με μηχανή και ψαλίδι, με λάδι στο τέλος.'),
    ('0a4fe7ec-d076-4e50-bf2f-17dfc898978e', '11111122-2222-4111-8111-111111111111', 'Beard trim', 'Beard trimming and tidying with clipper and scissors, finished with oil.'),
    ('ce317cd7-4411-432e-96ed-407a64c26c75', '11111122-2222-4111-8111-111111111112', 'Κούρεμα με ψαλίδι', 'Κούρεμα μόνο με ψαλίδι και χτένα, για φυσική υφή και μαλακές γραμμές.'),
    ('ce317cd7-4411-432e-96ed-407a64c26c75', '11111122-2222-4111-8111-111111111111', 'Scissor cut', 'A cut with scissors and comb only, for natural texture and soft lines.'),
    ('8392b94f-ced0-49d0-bff0-a9c7e9cddaaf', '11111122-2222-4111-8111-111111111112', 'Fade & γένια με ξυράφι', 'Skin fade και σχήμα γενιών με ξυράφι, με ζεστή πετσέτα στο τέλος.'),
    ('8392b94f-ced0-49d0-bff0-a9c7e9cddaaf', '11111122-2222-4111-8111-111111111111', 'Fade & razor beard', 'A skin fade and razor beard shaping, finished with a hot towel.'),
    ('6af1e91f-e538-46fe-9cac-80932acc1efa', '11111122-2222-4111-8111-111111111112', 'Σχήμα γενιών με ξυράφι', 'Καθαρές γραμμές στα μάγουλα και στον λαιμό με ξυράφι και ζεστό αφρό.'),
    ('6af1e91f-e538-46fe-9cac-80932acc1efa', '11111122-2222-4111-8111-111111111111', 'Razor beard shaping', 'Sharp cheek and neck lines with a straight razor and warm lather.'),
    ('e76e7605-b1bf-4446-a1d5-fa1930af2400', '11111122-2222-4111-8111-111111111112', 'Signature κούρεμα', 'Συμβουλή στυλ, κούρεμα, λούσιμο με μασάζ κεφαλής και styling με premium προϊόντα.'),
