-- Greek public holidays as closures. The showcase shop also closes in mid-August
-- and works short hours on 24 and 31 December. Orthodox Easter is a lookup.
WITH easter(day) AS (
    VALUES ('2024-05-05'::date), ('2025-04-20'), ('2026-04-12'), ('2027-05-02'), ('2028-04-16'), ('2029-04-08'),
           ('2030-04-28')
), years AS (
    SELECT generate_series(extract(year FROM CURRENT_DATE)::int - 3, extract(year FROM CURRENT_DATE)::int + 1) AS year
), closures AS (
    SELECT make_date(year, 1, 1) AS starts_on, make_date(year, 1, 1) AS ends_on, 'full' AS scope FROM years
    UNION ALL SELECT make_date(year, 1, 6), make_date(year, 1, 6), 'full' FROM years
    UNION ALL SELECT make_date(year, 3, 25), make_date(year, 3, 25), 'full' FROM years
    UNION ALL SELECT make_date(year, 5, 1), make_date(year, 5, 1), 'full' FROM years
    UNION ALL SELECT make_date(year, 8, 11), make_date(year, 8, 17), 'summer' FROM years
    UNION ALL SELECT make_date(year, 10, 28), make_date(year, 10, 28), 'oct28' FROM years
    UNION ALL SELECT make_date(year, 12, 25), make_date(year, 12, 26), 'christmas' FROM years
    UNION ALL SELECT day - 48, day - 48, 'full' FROM easter
    UNION ALL SELECT day + 1, day + 1, 'full' FROM easter
    UNION ALL SELECT day + 50, day + 50, 'full' FROM easter
), targets AS (
    SELECT id, 'showcase' AS tier FROM companies WHERE id IN ('b1c47b09-e8d1-4e86-be48-f593744e1088')
    UNION ALL SELECT id, 'medium' FROM companies WHERE id IN ('c9d5998f-becd-4568-83b4-5f83025a667d', 'a1cc6fc7-8590-4cf4-b229-a3dc7cd00a71', 'b40d79f1-afda-4853-8d57-54d00c07b735', '06c39c31-90a2-43a5-9124-4655e6ccd319')
    UNION ALL SELECT id, 'basic' FROM companies WHERE id IN ('a22fa02e-37bd-46ac-82ba-c74e6859b5f1', '2665614f-521e-4126-b924-bd20fdb18a03', 'e309846c-32de-4862-b06b-c0364976c0e7', 'e5bd6809-3883-40cf-b9c5-edb102369441', '18cf4c29-9238-4755-a50a-d283f5e37acc', 'fe1248a2-a5b2-4552-8e89-78e68bcf66a3', '5722a109-c20e-4981-bf12-387b4a686eda', '0ca576d9-d433-49f2-91a1-bcc30e45569c', '85851389-b522-41d6-930a-5e5c8c85e5f1', '65a4b4a7-65e4-4c6d-9ca1-7b533d566a90', '27acf4a2-a099-43b0-bca3-621e567fc058', '068bfa31-21f9-46cb-8592-88fe35ff7037', '00fab928-ebb1-4e2f-b000-d1c8c62ac48a', 'ee822d69-cfec-4246-b619-1ddbc8634b16', '2cd900b7-2c9d-4492-bcb8-303d9058dbf8', '8678993c-1235-4fb8-84c1-76d7334f07b6', '61077097-4ea3-4d85-b4db-da6c34447f78', '952dceeb-e96d-4507-83e6-cd58e666e3d2')
), picked AS (
    SELECT DISTINCT ON (targets.id, closures.starts_on) targets.id AS company_id, closures.starts_on, closures.ends_on
    FROM targets
    JOIN closures ON targets.tier = 'showcase'
                  OR (targets.tier = 'medium' AND closures.scope IN ('christmas', 'oct28', 'full'))
                  OR (targets.tier = 'basic' AND closures.scope IN ('oct28', 'christmas'))
    WHERE closures.ends_on >= CURRENT_DATE - 760 AND closures.starts_on <= CURRENT_DATE + 90
)
SELECT md5('seed:holiday:' || company_id || starts_on)::uuid, company_id, starts_on, ends_on, true, now() - interval '30 days'
FROM picked AS candidate
WHERE NOT EXISTS (SELECT 1 FROM picked AS other
                  WHERE other.company_id = candidate.company_id AND other.starts_on < candidate.starts_on
                    AND other.ends_on >= candidate.starts_on);

SELECT md5('seed:holiday:' || 'b1c47b09-e8d1-4e86-be48-f593744e1088' || day)::uuid, 'b1c47b09-e8d1-4e86-be48-f593744e1088'::uuid, day, day, false, '09:00', '15:00',
       now() - interval '30 days'
FROM (SELECT make_date(year, month, day_of_month) AS day
      FROM generate_series(extract(year FROM CURRENT_DATE)::int - 3, extract(year FROM CURRENT_DATE)::int) AS year,
           (VALUES (12, 24), (12, 31)) AS fixed(month, day_of_month)) AS days
WHERE day >= CURRENT_DATE - 760 AND day <= CURRENT_DATE + 90;



